import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { TabsExtended } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { ConfirmDialog } from "@sb-components/composites/feedback/ConfirmDialog/ConfirmDialog"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK ΓÇö `PlaygroundSetupSteps`: the ordered setup guide for a playground ΓÇö pair
 * the local agent, install the engine (an OS-tabbed guide), and ΓÇö Ollama flavor
 * only ΓÇö pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (┬º14d.2 ΓÇö see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs ΓÇö the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render ΓÇö named per ┬º"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model ΓÇö see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status ΓåÆ chip label/color ΓÇö fixed Vietnamese copy this block owns (┬º14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const onRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const onConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) ΓÇö built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={onRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired ΓÇö get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine ΓÇö skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id ΓÇö this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine ΓÇö once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh ΓÇö ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding ΓÇö ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use ΓÇö the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again ΓÇö Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return ΓÇö a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection ΓÇö getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={onConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

export { PlaygroundSetupSteps }

import type { Meta, StoryObj } from "@storybook/nextjs"
import { TrialConversionStrip, type TrialConversionStripPrice } from "@sb-components/starci/blocks/commerce/TrialConversionStrip/TrialConversionStrip"
import { PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { BlockAnatomy, type AnatomyNode } from "@sb-utils/BlockAnatomy/BlockAnatomy"

/**
 * BLOCK ΓÇö the trial -> enroll conversion strip on the content-home. Bundles a
 * loss-aversion line (free lessons remaining), the real price (+ phase-scarcity
 * note), and an enroll CTA. `src` is STORE-COUPLED (SWR price fetch + zustand
 * payment overlay) ΓÇö this port takes the SAME data as PLAIN PROPS (`price`,
 * `isSkeleton`, `onEnroll`) so it renders standalone. Leaves differ by
 * SHAPE: price loading (skeleton mirror) vs price landed (PriceTag +
 * PhaseScarcityNote), and by content (free lessons remaining vs none left).
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and carries its OWN
 * BlockAnatomy axis (Diagram + Tree) reflecting the parts THAT leaf composes ΓÇö
 * there is no separate consolidated "Anatomy" story.
 */
const meta: Meta<typeof TrialConversionStrip> = {
    title: "StarCi/Blocks/Commerce/TrialConversionStrip/TrialConversionStrip",
    component: TrialConversionStrip,
    tags: ["autodocs"],
    parameters: {
        layout: "fullscreen",
    },
}

export default meta

type Story = StoryObj<typeof TrialConversionStrip>

/** Frame each leaf's anatomy panel with breathing room, capped to the strip's real width. */
/**
 * Story canvas padding only. The SUBJECT's own width goes through `BlockAnatomy`'s
 * `renderClassName`, not wrapped here: wrapping it here would make the panel inherit
 * `max-w-xl` and squeeze its three text columns into 576px.
 */
const frame = (node: React.ReactNode) => <div data-tier="fixture" className="p-8">{node}</div>

/** Sample landed price preview ΓÇö early-bird phase, 22% off, 12 seats left before it rises. */
const SAMPLE_PRICE: TrialConversionStripPrice = {
    discountedPriceVnd: 1_990_000,
    originalPriceVnd: 2_990_000,
    phasePriceVnd: 2_490_000,
    discountPercent: 20,
    currentPhase: PricingPhase.EarlyBird,
    seatsRemainingInCurrentPhase: 12,
    nextPhasePriceVnd: 2_490_000,
}

// Header cluster ΓÇö IconTile + a two-line Typography pair ΓÇö is SHARED by every leaf below
// (only the price section + CTA differ), so it is one constant reused across the parts trees.
// This block goes through `SurfaceCard` Γèâ `StackV` Γèâ (`StackH` ┬╖ `Split`).
const SURFACE: AnatomyNode = {
    name: "SurfaceCard",
    tier: "composite",
    role: "card face ΓÇö radius/shadow/`padding` (default 3, matching the card `p-3` rule) comes from the scaffold, not hand-rolled",
    storyId: "composites-cards-surfacecard-surfacecard--default",
}
// WARNING: TRIED `Split` and it was WRONG: its contract is "the `start` side is allowed to
// SHRINK" => when tight it SQUEEZES the price column and the ΓêÆ33% chip drops to a new
// line. Price is a number, squeezing it makes no sense ΓÇö this row must WRAP (the button
// drops below), i.e. `StackH` with `wrap`.
// Name differs from the `StackH` node of the lead row: the panel groups nodes BY NAME,
// matching names would merge into one.
const PRICE_ROW: AnatomyNode = {
    name: "StackH",
    tier: "frame",
    role: "price Γåö CTA row ΓÇö `wrap` so the BUTTON drops to a new line when tight, the price column never gets squeezed",
    storyId: "frames-stack-stackh--default",
}

const HEADER_PARTS: Array<AnatomyNode> = [
    { name: "IconTile", tier: "atom", role: "the lock glyph in its tinted tile ΓÇö accent tone, sm (40px)", storyId: "atoms-display-icontile-icontile--default" },
    {
        name: "TitledText",
        tier: "composite",
        role: "the titleΓåödescription pair as ONE unit ΓÇö it owns the type scale (title sm medium, subtitle xs muted)",
        storyId: "composites-texts-titledtext--overview",
    },
]

// LOADING shape ΓÇö price section mirrors the eventual PriceTag + PhaseScarcityNote box with
// two Skeleton.Typography bars (h4 + body-xs) so layout never shifts once the price lands.
const BUTTON: AnatomyNode = { name: "Button", tier: "atom", role: "unlock CTA ΓÇö always renders, doesn't wait for the price", storyId: "atoms-buttons-button-button--default" }

/** Wraps content in the EXACT scaffold set the block builds: SurfaceCard Γèâ StackV Γèâ (StackH ┬╖ Split). */
const framed = (priceSide: Array<AnatomyNode>): Array<AnatomyNode> => [
    {
        ...SURFACE,
        children: [
            {
                name: "StackV",
                tier: "frame",
                role: "column inside the card ΓÇö `gap-6` seam between the lead cluster and the price block (replaces the removed `border-t`)",
                storyId: "frames-stack-stackv--default",
                children: [
                    {
                        name: "StackH",
                        tier: "frame",
                        role: "lead row ΓÇö icon Γåö text cluster, center-aligned",
                        storyId: "frames-stack-stackh--default",
                        children: HEADER_PARTS,
                    },
                    {
                        ...PRICE_ROW,
                        children: [
                            {
                                // Name MUST differ from the outer `StackV` node: the panel
                                // groups nodes BY NAME, two `StackV`s with the same name
                                // would MERGE into one and misread the tree.
                                name: "StackV",
                                tier: "frame",
                                role: "LEFT side of the Split ΓÇö price column + scarcity line",
                                storyId: "frames-stack-stackv--default",
                                children: priceSide,
                            },
                            BUTTON,
                        ],
                    },
                ],
            },
        ],
    },
]

const LOADING_PARTS: Array<AnatomyNode> = framed([
    // These two bars ARE `Typography isSkeleton` ΓÇö a real component, so they need
    // a door. Without a `storyId` they emit DOM but never enter the tree (┬º11a whitelist).
    { name: "Typography", tier: "atom", role: "mirrors one of the two waiting lines ΓÇö the price (h4, 1/3 width) or the seats line (body-xs, 1/2 width)", storyId: "atoms-text-typography-typography--overview" },
])

// LOADED shape ΓÇö price landed: PriceTag owns the discount, PhaseScarcityNote sits as a
// sibling below owning scarcity (orthogonal urgency, per PhaseScarcityNote's own doc).
const LOADED_PARTS: Array<AnatomyNode> = framed([
    { name: "PriceTagProminent", tier: "block", role: "amount due + struck-through original price + savings chip", storyId: "starci-blocks-commerce-pricetag--with-discount" },
    // `PhaseScarcityNote` HAS `anatPart` so it can merge into ONE node.
    { name: "PhaseScarcityNote", tier: "block", role: "seats left in the current phase + the price it rises to", storyId: "starci-blocks-commerce-phasescarcitynote-phasescarcitynote--default" },
    { name: "Button", tier: "atom", role: "CTA to unlock the whole course", storyId: "atoms-buttons-button-button--default" },
])

/**
 * Leaf for `isSkeleton`. Only the PRICE region rests ΓÇö the header and the CTA do not
 * depend on the price, so they render at once and the two shimmer bars stand exactly where
 * PriceTag + PhaseScarcityNote will land, which is what keeps the layout from jumping.
 *
 * A leaf is named after the TRUC it draws, and the prop is `isSkeleton` at every tier.
 */
export const Skeleton: Story = {
    render: () =>
        frame(
            <BlockAnatomy
                name="TrialConversionStrip"
                tier="block"
                leaf="Prop `isSkeleton`"
                renderClassName="mx-auto max-w-xl"
                parts={LOADING_PARTS}
                reason="Only the PRICE region rests. The header and the CTA do not depend on the price, so they render at once and the two shimmer bars stand exactly where PriceTag and PhaseScarcityNote will land, which is what stops the layout jumping when the price arrives."
                states={[
                    {
                        name: "isSkeleton, price not yet arrived",
                        why: "`PriceTag` and `PhaseScarcityNote` are replaced by two shimmer bars sized to the box they will occupy. The block draws its own resting shape rather than waiting on a shared skeleton component, so whoever owns the shape owns how it rests.",
                        code: `<TrialConversionStrip
    freeLessonsRemaining={3}
    isSkeleton
    onEnroll={handleEnroll}
/>`,
                        render: (
                            <TrialConversionStrip
                                freeLessonsRemaining={3}
                                isSkeleton
                                onEnroll={() => {}}

                            />
                        ),
                    },
                ]}
            />,
        ),
}

/** Story: resting state for this component. */
export const Default: Story = {
    render: () =>
        frame(
            <BlockAnatomy
                name="TrialConversionStrip"
                tier="block"
                leaf="Default"
                renderClassName="mx-auto max-w-xl"
                parts={LOADED_PARTS}
                reason="The strip carries three honest levers on the surface the learner is already standing on, namely what they lose by stopping, how scarce the current price is, and the single button that ends the decision. Every number arrives as a prop from the caller, so this block never fabricates a price, a seat count or a deadline."
                states={[
                    {
                        name: "freeLessonsRemaining = 3",
                        why: "The description names how many free lessons are still unread. Loss aversion works harder than a discount here, because the learner already owns something they are about to leave behind.",
                        code: `<TrialConversionStrip
    freeLessonsRemaining={3}
    price={price}
    onEnroll={handleEnroll}
/>`,
                        render: (
                            <TrialConversionStrip
                                freeLessonsRemaining={3}
                                price={SAMPLE_PRICE}
                                onEnroll={() => {}}

                            />
                        ),
                    },
                    {
                        name: "freeLessonsRemaining = 0",
                        why: "Only the `subtitle` string changes and the node tree stays identical to the first state. With nothing free left the loss argument is spent, so the sentence switches to the closing line that asks for the purchase.",
                        code: `<TrialConversionStrip
    freeLessonsRemaining={0}
    price={price}
    onEnroll={handleEnroll}
/>`,
                        render: (
                            <TrialConversionStrip
                                freeLessonsRemaining={0}
                                price={SAMPLE_PRICE}
                                onEnroll={() => {}}

                            />
                        ),
                    },
                ]}
            />,
        ),
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Popover } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Chip } from "@/components/atoms/chips/Chip"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { KeyValueList } from "@/components/composites/data/KeyValue"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * DESIGN ΓÇö a single course/product price: the amount to pay (bold), the struck
 * list price, a `ΓêÆX%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes ΓÇö
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface ΓÇö decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (┬º14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list -> phase -> charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Every word the breakdown popover says ΓÇö resolved by the connected {@link PriceTag}. */
export interface PriceTagLabels {
    /** Popover heading, and its accessible name. */
    breakdownTitle: string
    /** Row label for the pre-discount price. */
    listPrice: string
    /** Row label for the phase discount (already folded with the phase name when there is one). */
    phaseRow: string
    /** Row label for the loyalty discount (already folded with the loyalty note when there is one). */
    loyaltyRow: string
    /** Row label for the total the buyer actually pays. */
    youPay: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** Breakdown-popover copy, already localized. A story passes i18n keys. */
    labels: PriceTagLabels
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
 * `true` -> the price is in its RESTING state: the amount, the struck-through
 * original price, the `ΓêÆX%` chip, and the saving line all turn to shimmer,
 * KEEPING the same line boxes so nothing jumps in layout (┬º8).
 *
 * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
 * `Chip`), instead of building a second shimmer tree (┬º12c). The popover
 * is TURNED OFF while resting ΓÇö there is no data to open yet, and a pressable
 * control while loading is a false promise.
 */
    isSkeleton?: boolean
    /**
 * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
 * there IS a saving the `ΓêÆX%` chip is ALWAYS a button that opens the popover (at
 * minimum list price -> "you pay"); `breakdown` just adds the middle steps that
 * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
 */
    breakdown?: PriceBreakdown
    /**
 * Show the concrete "save NΓé½" line under the price (the real VND saved, not just
 * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
 */
    showSavingLine?: boolean
    /** Where the root sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Role -> amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role -> struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
export const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}Γé½`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `ΓêÆX%` success chip whose percent is the REAL list -> charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price -> you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    classNames,
    labels,
}: PriceTagProps & { emphasis: PriceEmphasis }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the ΓêÆX% saving chip ΓÇö composed from the `Chip` atom (tone success ->
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`ΓêÆ${savePercent}%`}
            />
        ) : null

    // phase saving = list -> phase ; loyalty saving = phase -> charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content ΓÇö shown for EVERY saving (so the chip is always clickable), at
    // minimum list price -> you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left <-> value right, repeated =>
        // exactly `KeyValueList` (a repeated list => `items` is DATA). The "you
        // pay" row is the TOTAL row => `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // WARNING∩╕Å The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // WARNING∩╕Å This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` ΓÇö that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={4} principle="cell-pad"
            explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} body={() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text={labels.breakdownTitle} isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the ┬º10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which ┬º10 forbids ΓÇö a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: labels.listPrice,
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: labels.phaseRow,
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` ΓÇö this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` ΓÇö left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `ΓêÆ${formatPrice(original - breakdown.phase, currency)} (ΓêÆ${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: labels.loyaltyRow,
                                            // See the "phase" row's note above ΓÇö same loss of the green tint,
                                            // same reason.
                                            value: `ΓêÆ${formatPrice(breakdown.phase - discounted, currency)} (ΓêÆ${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: labels.youPay,
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t ΓÇª pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight => exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment ΓÇö merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (┬º9c), NOT raw
                // HeroUI ΓÇö thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-2/3"] : undefined}

                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck
                            classNames={isSkeleton ? ["w-1/3"] : undefined}

                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover ΓÇö there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label={labels.breakdownTitle}
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}
            classNames={isSkeleton ? ["w-1/2"] : undefined}

            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row ┬╖ the "saving" line) =>
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (┬º13b).
        <StackV
            // `grouped` (┬º10b): the price row and the saving line are two DIFFERENT vertical
            // rows of one design. It was `tight` (1), which ┬º10b reserves for pairs sitting
            // inside a lower-tier component ΓÇö the saving line read as if it were glued under the number.
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Chip } from "@/components/atoms/chips/Chip"
import { Button } from "@/components/atoms/buttons/Button"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `WeeklyChallengeCard`: "Weekly Challenge" ΓÇö the featured challenge of
 * the week. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 * LEAF by STRUCTURE (┬º14d.2): whether the viewer already passed, already
 * claimed, or the leaderboard is short, are all DATA conditions of the same
 * status row/list ΓÇö never a different shape this block draws ΓÇö so this block
 * has exactly ONE leaf ("Content"), the same shape `LeaderboardBoard`'s single
 * `Board` leaf uses.
 */

/** One leaderboard row: a finisher who already passed this week's challenge. */
export interface WeeklyChallengeLeaderboardEntry {
    /** Stable React key ΓÇö the finisher's username. */
    key: string
    /** Account username; drives the avatar fallback (same contract as {@link UserCell}). */
    username: string
    /** Uploaded avatar URL, or `null`/omitted ΓÇö a generated default is shown instead. */
    avatar?: string | null
    /** Already-worded "x ago" label (e.g. "5 minutes ago"). */
    passedAtLabel: string
}

/** The currently featured weekly-challenge event. */
export interface WeeklyChallengeData {
    /** Title of the featured challenge. */
    title: string
    /** Fired from the title AND the "Try it now" prompt ΓÇö the caller already resolved the route. Omit when not routable. */
    onOpenChallenge?: () => void
    /** Already-worded countdown to the event's close (e.g. "2 days 6 hours left"). Omit while unknown. */
    endsInLabel?: string
    /** Whether the viewer has already passed the challenge this week. */
    viewerPassed: boolean
    /** Whether the viewer already claimed the reward this week. Ignored unless `viewerPassed`. */
    claimed: boolean
    /** Coin reward for claiming; `null` when the viewer hasn't passed yet. */
    coinReward: number | null
    /** `true` -> the claim mutation is in flight ΓÇö disables + spins the claim button. */
    isClaiming?: boolean
    /** Fired when the viewer presses the claim button. Required whenever `viewerPassed && !claimed`. */
    onClaim?: () => void
    /** Total number of users who have passed so far. */
    passedCount: number
    /** Top finishers (already capped by the caller), newest first. */
    leaderboard: Array<WeeklyChallengeLeaderboardEntry>
}

/** Props for {@link WeeklyChallengeCard}. */
export interface WeeklyChallengeCardProps {
    /** True while the first load is running ΓÇö {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** True (once loaded) -> no challenge event is currently active. */
    isEmpty: boolean
    /** Truthy -> the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The featured challenge. Required once loaded and non-empty. */
    data?: WeeklyChallengeData
    /** `true` -> every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** The title: a routable link when `onOpenChallenge` is set, plain bold text otherwise. */
const titleText = (data: WeeklyChallengeData, isSkeleton: boolean) =>
    data.onOpenChallenge ? (
        <Typography
            size="sm"
            isLink
            isSkeleton={isSkeleton}
            onPress={data.onOpenChallenge}
            text={data.title}

        />
    ) : (
        <Typography
            size="sm"
            weight="bold"
            isSkeleton={isSkeleton}
            text={data.title}

        />
    )

/** Right side of the status row: claimed chip, a pending claim button, or a "try now" prompt. */
const statusSlot = (data: WeeklyChallengeData, isSkeleton: boolean) => {
    if (isSkeleton) {
        return <Chip isSkeleton />
    }
    if (!data.viewerPassed) {
        return data.onOpenChallenge ? (
            <Typography
                size="xs"
                isLink
                onPress={data.onOpenChallenge}
                text="Try it now"

            />
        ) : null
    }
    if (data.claimed) {
        return (
            <Chip tone="success" text="Completed" />
        )
    }
    return (
        <Button
            variant="primary"
            size="sm"
            isPending={data.isClaiming}
            onPress={data.onClaim}
            label={`Claim ${data.coinReward ?? 0} coins`}
        />
    )
}

/** Builds one finisher's free-form `SurfaceCardList` content: the unchanged `UserCell`. */
const finisherItem = (entry: WeeklyChallengeLeaderboardEntry, isSkeleton: boolean): SurfaceCardListItem => ({
    key: entry.key,
    content: () => (
        <div>
            <UserCell
                username={entry.username}
                avatar={entry.avatar}
                trailing={({ isSkeleton: slotSkeleton }: SkeletonProps) => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={slotSkeleton}
                        text={slotSkeleton ? undefined : entry.passedAtLabel}

                    />
                )}
                isSkeleton={isSkeleton}

            />
        </div>
    ),
})

/** Fixed-shape placeholder rendered while {@link WeeklyChallengeCardProps.isLoading} ΓÇö no real event exists yet. */
const LOADING_DATA: WeeklyChallengeData = {
    title: "",
    viewerPassed: false,
    claimed: false,
    coinReward: null,
    passedCount: 0,
    leaderboard: Array.from({ length: 3 }, (_, index) => ({ key: `loading-${index}`, username: "", passedAtLabel: "" })),
}

/** Props for the internal {@link Content} tree ΓÇö reused for both the real render and the loading skeleton. */
interface ContentProps {
    data: WeeklyChallengeData
    isSkeleton: boolean
}

const Content = ({ data, isSkeleton }: ContentProps) => {
    const statusRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between" align="center" items={[
                () => (data.endsInLabel != null || isSkeleton ? (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : data.endsInLabel}

                    />
                ) : <span />),
                () => statusSlot(data, isSkeleton),
            ]} />
    )

    return (
        <StackV gap={4} items={[
            () => titleText(data, isSkeleton),
            () => statusRow,
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={isSkeleton ? undefined : `${data.passedCount} people have passed`}

                />
            ),
            ...(data.leaderboard.length > 0 ? [() => (
                <div>
                    <SurfaceCardList
                        variant="nested"
                        items={data.leaderboard.map((entry) => finisherItem(entry, isSkeleton))}

                    />
                </div>
            )] : []),
        ]} />
    )
}

/**
 * "Weekly Challenge" ΓÇö the featured weekly-challenge card. See the file header
 * for the full contract.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
const WeeklyChallengeCard = ({
    isLoading,
    isEmpty,
    error,
    onRetry,
    data,
    isSkeleton = false,
}: WeeklyChallengeCardProps) => (
    <SurfaceCard
        label="Weekly Challenge"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => <Content data={LOADING_DATA} isSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{
                    title: "No challenge is currently active",
                    description: "Check back next week for a new challenge.",
                }}
                error={error}
                errorContent={{
                    title: "Couldn't load the weekly challenge",
                    description: "Try again for the latest info.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content data={data} isSkeleton={isSkeleton} />
                ) : null)}
            />
        )}
    />
)

export { WeeklyChallengeCard }

type NumberCellProps = { value?: number }

type UnifiedRowProps = { line: DiffLine }

type SplitCellProps = { line: DiffLine | null; side: "old" | "new" }

"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** The kind of a diff line: an addition, a deletion, or unchanged context. */
export type DiffLineType = "add" | "del" | "ctx"

/** One pre-parsed line of a diff. The caller does the diffing; this block only renders. */
export interface DiffLine {
    /** Whether the line was added, removed, or is unchanged context. */
    type: DiffLineType
    /** The raw text content of the line (without the leading +/-/space marker). */
    content: string
    /** Line number in the OLD file. Omit for pure additions. */
    oldNumber?: number
    /** Line number in the NEW file. Omit for pure deletions. */
    newNumber?: number
}

/** A contiguous group of diff lines, optionally introduced by a hunk header. */
export interface DiffHunk {
    /** Optional hunk header (e.g. "@@ -1,4 +1,5 @@" or a section label). */
    header?: string
    /** The pre-parsed lines that make up this hunk. */
    lines: DiffLine[]
}

/** How the diff is laid out. */
export type DiffViewerVariant = "unified" | "split"

/**
 * Props for the {@link DiffViewer} block.
 *
 * Tier-3 presentational: props-only, no store/SWR/fetch, and no diff ALGORITHM ΓÇö
 * the caller supplies already-parsed hunks. Used for grading feedback that
 * compares student code against a suggested fix.
 */
export interface DiffViewerProps extends WithClassNames<undefined> {
    /** Optional filename shown in the header bar above the diff (e.g. "src/auth.ts"). */
    filename?: string
    /** The pre-parsed hunks to render, in order. */
    hunks: DiffHunk[]
    /**
     * Layout variant. `"unified"` (default) stacks all lines in a single column;
     * `"split"` places the old file on the left and the new file on the right.
     */
    variant?: DiffViewerVariant
}

/** type ΓåÆ row background + text color classes (tokens only). */
const LINE_TONE: Record<DiffLineType, string> = {
    add: "bg-success-soft text-success-soft-foreground",
    del: "bg-danger-soft text-danger-soft-foreground",
    ctx: "text-foreground",
}

/** type ΓåÆ the leading marker glyph in the unified gutter. */
const LINE_MARKER: Record<DiffLineType, string> = {
    add: "+",
    del: "-",
    ctx: " ",
}

/** A monospace line-number cell in the gutter (right-aligned, non-selectable). */
const NumberCell = ({ value }: NumberCellProps) => (
    <span className="w-10 shrink-0 select-none pr-2 text-right tabular-nums text-muted-foreground">
        {value ?? ""}
    </span>
)

/** One rendered line in the UNIFIED layout: [old #][new #][marker][content]. */
const UnifiedRow = ({ line }: UnifiedRowProps) => (
    <div className={cn("flex items-start", LINE_TONE[line.type])}>
        <NumberCell value={line.oldNumber} />
        <NumberCell value={line.newNumber} />
        <span className="w-4 shrink-0 select-none text-center">
            {LINE_MARKER[line.type]}
        </span>
        <span className="whitespace-pre pr-4">{line.content}</span>
    </div>
)

/** One side of the SPLIT layout: a single line number + content, or a blank filler row. */
const SplitCell = ({ line, side }: SplitCellProps) => (
    <div
        className={cn(
            "flex items-start",
            // A filler cell (no line on this side) stays neutral; a real line gets its tone.
            line ? LINE_TONE[line.type] : "text-foreground",
        )}
    >
        <NumberCell value={side === "old" ? line?.oldNumber : line?.newNumber} />
        <span className="whitespace-pre pr-4">{line ? line.content : ""}</span>
    </div>
)

/**
 * DiffViewer renders a code diff for grading feedback ΓÇö student code versus a
 * suggested fix. It accepts PRE-PARSED hunks (no diff algorithm lives here) and
 * shows a filename header bar, a line-number gutter, and token-colored line
 * backgrounds: additions use `bg-success-soft`, deletions `bg-danger-soft`, and
 * context stays neutral. Long lines never break the page ΓÇö the code area scrolls
 * horizontally inside its own `overflow-x-auto` container.
 *
 * `variant="unified"` (default) stacks every line in one column with +/-/space
 * markers. `variant="split"` places the old file on the left and the new file on
 * the right; each source line lands on its own side while context appears on both.
 *
 * Tier-3 presentational block: props-only, no store, no SWR, no side-effects.
 *
 * @param props - {@link DiffViewerProps}
 *
 * @example
 * <DiffViewer
 *     filename="src/auth.ts"
 *     hunks={[{ header: "@@ -1,3 +1,4 @@", lines: [
 *         { type: "ctx", content: "function login() {", oldNumber: 1, newNumber: 1 },
 *         { type: "del", content: "  return true", oldNumber: 2 },
 *         { type: "add", content: "  return verify(token)", newNumber: 2 },
 *     ] }]}
 * />
 * @see Story: .storybook/stories/blocks/grading/DiffViewer/DiffViewer.stories
 */
export const DiffViewer = ({
    filename,
    hunks,
    variant = "unified",
    className,
}: DiffViewerProps) => {
    return (
        <div
            className={cn(
                "overflow-hidden rounded-xl border border-default bg-surface",
                className,
            )}
        >
            {/* Filename header bar ΓÇö sits above the scrollable code area */}
            {filename ? (
                <div className="border-b border-default bg-default px-4 py-2">
                    <Typography type="body-sm" weight="medium" className="font-mono">
                        {filename}
                    </Typography>
                </div>
            ) : null}

            {/* Horizontal-scroll container so long lines never break the page */}
            <div className="overflow-x-auto">
                <div className="min-w-fit py-1 font-mono text-xs leading-relaxed">
                    {hunks.map((hunk, hunkIndex) => (
                        <div key={hunkIndex}>
                            {/* Optional hunk header ΓÇö muted separator row */}
                            {hunk.header ? (
                                <div className="whitespace-pre bg-default px-4 py-1 text-muted-foreground">
                                    {hunk.header}
                                </div>
                            ) : null}

                            {variant === "split"
                                ? hunk.lines.map((line, lineIndex) => (
                                    <div
                                        key={lineIndex}
                                        className="grid grid-cols-2 divide-x divide-default"
                                    >
                                        {/* Old side hides pure additions; new side hides pure deletions */}
                                        <SplitCell
                                            line={line.type === "add" ? null : line}
                                            side="old"
                                        />
                                        <SplitCell
                                            line={line.type === "del" ? null : line}
                                            side="new"
                                        />
                                    </div>
                                ))
                                : hunk.lines.map((line, lineIndex) => (
                                    <UnifiedRow key={lineIndex} line={line} />
                                ))}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}

import { CaretDownIcon, LockIcon, SparkleIcon, WarningCircleIcon, WarningIcon } from "@phosphor-icons/react"
import React, { useMemo, useState } from "react"
import {
    Button,
    Chip,
    Dropdown,
    DropdownItem,
    DropdownMenu,
    DropdownPopover,
    DropdownSection,
    DropdownTrigger,
    ScrollShadow,
    SearchField,
    Separator,
    Tooltip,
    Typography,
    cn
} from "@heroui/react"
import { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"
import { AiModelCategory, AiModelTask } from "@/modules/api/graphql/queries/query-ai-models"
import { type AiGradableModel } from "@/modules/api/graphql/queries/types/ai-models"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { AiCategoryChip } from "@/components/blocks/chips/AiCategoryChip"
import { SelfHostGpuMark } from "@/components/blocks/grading/SelfHostGpuMark"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import type { ModelHealth } from "@/hooks/socketio/useAiModelLatency"

/**
 * Model selection emitted by the picker. `model`/`provider` null = the Auto
 * lane (the balancer picks); type ModelRowLayoutProps = {
    leading?: React.ReactNode
    name: string
    nameSuffix?: React.ReactNode
    isSelected?: boolean
    muted?: boolean
    trailing: React.ReactNode
}

a pinned model runs on that model. Structurally
 * matches feature selection types (e.g. ChallengeGradeSelection) so callers
 * pass theirs directly.
 */
export interface GradeModelSelection {
    /** Pinned model name, or null for the Auto lane. */
    model: string | null
    /** Provider of the pinned model, or null for the Auto lane. */
    provider: ModelProvider | null
}

/** Categories that need an unlock (paid OR enrolled) to pick. */
const PLAN_CATEGORIES: ReadonlyArray<AiModelCategory> = [
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/** Category ladder cheapest ΓåÆ strongest ΓÇö for "below the floor" comparison. */
const CATEGORY_ORDER: ReadonlyArray<AiModelCategory> = [
    AiModelCategory.Low,
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/** Tier facet options (incl. the "all" reset). */
export const TIER_FILTERS: ReadonlyArray<AiModelCategory | "all"> = [
    "all",
    AiModelCategory.Low,
    AiModelCategory.Medium,
    AiModelCategory.High,
]

/**
 * Live health badge on each model row ΓÇö a green dot + latency (up) or a red dot
 * + "down" (failing probe), styled like the category chip. Driven by the public
 * `aiModelLatency` snapshot + `/system_health` socket; rendered only when data exists.
 */
const ModelHealthChip = ({ ok, errorMessage, latencyLabel, downLabel }: ModelHealth & { latencyLabel: string, downLabel: string }) => {
    const chip = (
        <Chip
            color={ok ? "success" : "danger"}
            variant="soft"
            size="sm"
        >
            <span className={cn("size-1.5 rounded-full", ok ? "bg-success" : "bg-danger")} />
            <Chip.Label>
                {ok ? latencyLabel : downLabel}
            </Chip.Label>
        </Chip>
    )

    if (!ok && errorMessage) {
        return (
            <Tooltip>
                <Tooltip.Trigger className="shrink-0 cursor-default">
                    {chip}
                </Tooltip.Trigger>
                <Tooltip.Content>{errorMessage}</Tooltip.Content>
            </Tooltip>
        )
    }

    return <span className="shrink-0">{chip}</span>
}

/**
 * A model served by the `local` provider runs on StarCi GPU hardware by
 * definition, so the provider alone decides the mark.
 */
const showSelfHostMark = (model: AiGradableModel) =>
    model.provider === ModelProvider.Local

/** Dropdown row width ΓÇö popover must be bounded or `truncate` never fires. */
const DROPDOWN_POPOVER_CLASS = "w-80 max-w-[calc(100vw-2rem)]"
const DROPDOWN_ITEM_ROW_CLASS = "w-full min-w-0 overflow-hidden"

/**
 * HeroUI's `Select.Indicator` chevron, replicated 1:1 (same 16├ù16 viewBox + path)
 * so the `isDropdown` trigger's caret is IDENTICAL to the Select dropdowns beside
 * it ΓÇö `IconChevronDown` is a HeroUI internal, not exported, so we inline its SVG.
 */
const FieldChevronDown = () => (
    <svg aria-hidden="true" fill="none" viewBox="0 0 16 16" className="size-4">
        <path
            clipRule="evenodd"
            fillRule="evenodd"
            fill="currentColor"
            d="M2.97 5.47a.75.75 0 0 1 1.06 0L8 9.44l3.97-3.97a.75.75 0 1 1 1.06 1.06l-4.5 4.5a.75.75 0 0 1-1.06 0l-4.5-4.5a.75.75 0 0 1 0-1.06"
        />
    </svg>
)
const MODEL_ROW_TRIGGER_CLASS = "block w-full min-w-0"

/** Model row ΓÇö name truncates on the left, chips stay pinned on the right. */
const ModelRowLayout = ({
    leading,
    name,
    nameSuffix,
    isSelected,
    muted,
    trailing,
}: ModelRowLayoutProps) => (
    <div
        className={cn(
            "grid w-full grid-cols-[minmax(0,1fr)_auto] items-center gap-2",
            muted && "text-muted",
        )}
    >
        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
            {leading}
            <span
                className={cn("min-w-0 truncate", isSelected && "text-accent-soft-foreground")}
                title={name}
            >
                {name}
            </span>
            {nameSuffix}
        </span>
        <span className="flex shrink-0 items-center justify-end gap-2">{trailing}</span>
    </div>
)

/** Props for {@link GradeModelDropdown}. */
export type GradeModelDropdownProps = WithClassNames<undefined> & {
    /** Enabled models the user can pick from (from the `aiModels` catalog). */
    models: Array<AiGradableModel>
    /** The current lane + model selection. */
    selection: GradeModelSelection
    /** Whether higher-tier models are unlocked for this user (paid OR enrolled). */
    canPremium: boolean
    /** Disables the whole control (e.g. while a grade is in flight). */
    isDisabled?: boolean
    /** Show the "Auto" lane entry on top. Default true. */
    showAutoLane?: boolean
    /** Recommended minimum category. Any model BELOW it is flagged WARNING. */
    floor?: AiModelCategory
    /** Only show models suited for this task (chatting / grading). */
    task?: AiModelTask
    /** Popover placement. Default "bottom start"; pass "top start" for a bottom-anchored composer. */
    placement?: "bottom start" | "top start"
    /** Render the trigger as a standard bordered field-style dropdown button. */
    isDropdown?: boolean
    /** Render the trigger as a real `Button` (`variant="tertiary"`). */
    isButton?: boolean
    /** `isButton` only ΓÇö stretch the trigger `Button` to the full width of its container. */
    isButtonFullWidth?: boolean
    /** Fired with the new selection when the user picks an option. */
    onSelect: (selection: GradeModelSelection) => void
    /** Fired when a locked (unlock-required) model is pressed ΓÇö route to plans. */
    onUpgrade: () => void
    /** Live per-model health (dot + latency chip on each row); empty until the BE ships it. */
    latency: Map<string, ModelHealth>
    /** Already-localized "Auto" lane title (used as both the entry label and the fallback trigger label). */
    autoLaneLabel: string
    /** Already-localized "pick a model" trigger fallback (Auto lane hidden, nothing picked yet). */
    pickModelLabel: string
    /** Already-localized model-search field placeholder/aria-label. */
    searchModelLabel: string
    /** Already-localized "no models match" empty-search row label. */
    searchModelEmptyLabel: string
    /** Already-localized tier-filter aria-label. */
    filterTierLabel: string
    /** Already-localized "All" tier-filter option label. */
    filterAllLabel: string
    /** Already-localized tier label per category (for the inline tier filter + tooltips). */
    tierLabels: Record<AiModelCategory, string>
    /** Already-localized "model unavailable" tooltip text. */
    modelUnavailableLabel: string
    /** Already-localized "subscribe to unlock" tooltip text. */
    subscribeToGradeLabel: string
    /** Already-localized below-floor warning tooltip text. */
    belowFloorWarningLabel: string
    /** Already-localized off-task warning tooltip text. */
    offTaskWarningLabel: string
    /** Already-localized "hide hidden models" toggle label. */
    hideHiddenModelsLabel: string
    /** Already-localized, count-bound "show N hidden models" toggle label. */
    showHiddenModelsLabel: (count: number) => string
    /** Already-localized, ms-bound live-latency chip label. */
    latencyLabel: (ms: number) => string
    /** Already-localized "down" health-chip label. */
    downLabel: string
}

/**
 * Shared lane + model picker (grading, AI lab, any model-select surface).
 *
 * Renders the "Auto" lane plus every catalog model (tagged with its cost
 * category chip). Per model:
 * - no working key ΓåÆ DISABLED (warning, not selectable).
 * - Balanced / Premium / Frontier without an unlock ΓåÆ LOCKED (routes to plans).
 * - below the `floor` ΓåÆ SELECTABLE but flagged WARNING (may be inaccurate).
 * - otherwise ΓåÆ normal selectable.
 *
 * @param props - {@link GradeModelDropdownProps}
 */
export const _GradeModelDropdown = ({
    models,
    selection,
    canPremium,
    isDisabled = false,
    showAutoLane = true,
    floor,
    task,
    placement = "bottom start",
    isDropdown,
    isButton = false,
    isButtonFullWidth = false,
    onSelect,
    onUpgrade,
    latency,
    autoLaneLabel,
    pickModelLabel,
    searchModelLabel,
    searchModelEmptyLabel,
    filterTierLabel,
    filterAllLabel,
    tierLabels,
    modelUnavailableLabel,
    subscribeToGradeLabel,
    belowFloorWarningLabel,
    offTaskWarningLabel,
    hideHiddenModelsLabel,
    showHiddenModelsLabel,
    latencyLabel,
    downLabel,
    className,
}: GradeModelDropdownProps) => {
    // controlled open so selecting Auto can close the popover on press.
    const [isOpen, setIsOpen] = useState(false)
    const [query, setQuery] = useState("")
    const normalizedQuery = query.trim().toLowerCase()
    // single inline facet: tier.
    const [tierFilter, setTierFilter] = useState<AiModelCategory | "all">("all")
    // down (unavailable) + off-task models are HIDDEN by default; `showHidden` reveals them.
    const [showHidden, setShowHidden] = useState(false)
    const { visibleModels, hiddenCount } = useMemo(() => {
        const visible: Array<AiGradableModel> = []
        let hidden = 0
        for (const model of models) {
            if (normalizedQuery
                && !model.model.toLowerCase().includes(normalizedQuery)) {
                continue
            }
            if (tierFilter !== "all" && model.category !== tierFilter) {
                continue
            }
            const offTask = Boolean(task
                && model.supportedTasks?.length
                && !model.supportedTasks.includes(task))
            if (!model.available || offTask) {
                hidden += 1
                if (!showHidden) {
                    continue
                }
            }
            visible.push(model)
        }
        return { visibleModels: visible, hiddenCount: hidden }
    }, [models, normalizedQuery, tierFilter, task, showHidden])
    // tiers present in the catalog ΓåÆ the inline tier filter only offers real buckets.
    const tierChips = useMemo(() => {
        const present = new Set(models.map((model) => model.category))
        return TIER_FILTERS.filter((tier) => tier === "all" || present.has(tier))
    }, [models])
    // a pinned model shows its name; otherwise the Auto label (or "pick a model"
    // when the Auto lane is hidden and nothing is picked yet)
    const triggerLabel = selection.model
        ?? (showAutoLane ? autoLaneLabel : pickModelLabel)

    return (
        <Dropdown
            isOpen={isOpen}
            onOpenChange={(open) => {
                setIsOpen(open)
                if (!open) {
                    setQuery("")
                    setTierFilter("all")
                    setShowHidden(false)
                }
            }}
        >
            {isButton ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("cursor-pointer", isButtonFullWidth && "block w-full", className)}
                >
                    <Button variant="tertiary" size="sm" fullWidth={isButtonFullWidth}>
                        <SparkleIcon aria-hidden className="size-4 shrink-0" />
                        <span className={cn("truncate", isButtonFullWidth ? "min-w-0 flex-1 text-left" : "max-w-40")}>
                            {triggerLabel}
                        </span>
                    </Button>
                </DropdownTrigger>
            ) : isDropdown ? (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn(
                        "relative flex! min-h-9 w-full cursor-pointer items-center rounded-field border border-[color:var(--field-border)] bg-field py-2 pe-7 ps-3 text-sm text-field-foreground shadow-field transform-none!",
                        "hover:bg-field-hover hover:border-[color:var(--field-border-hover)]",
                        "data-[hovered=true]:bg-field-hover data-[hovered=true]:border-[color:var(--field-border-hover)]",
                        "data-[focus-visible=true]:border-[color:var(--field-border-focus)]",
                        className,
                    )}
                >
                    <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                        <SparkleIcon className="size-4 shrink-0" />
                        <span className="truncate">{triggerLabel}</span>
                    </span>
                    <span
                        className={cn(
                            "absolute inset-y-0 end-2 my-auto flex shrink-0 items-center justify-center text-field-placeholder transition duration-150",
                            isOpen && "rotate-180",
                        )}
                    >
                        <FieldChevronDown />
                    </span>
                </DropdownTrigger>
            ) : (
                <DropdownTrigger
                    isDisabled={isDisabled}
                    className={cn("min-w-0 max-w-full cursor-pointer", className)}
                >
                    <div className="flex w-full min-w-0 items-center justify-between gap-2">
                        <span className="flex min-w-0 items-center gap-2 overflow-hidden">
                            <SparkleIcon className="size-4 shrink-0" />
                            <span className="truncate">{triggerLabel}</span>
                        </span>
                        <CaretDownIcon weight="bold" className="size-4 shrink-0" />
                    </div>
                </DropdownTrigger>
            )}
            <DropdownPopover
                placement={placement}
                className={DROPDOWN_POPOVER_CLASS}
            >
                <div className="flex w-full min-w-0 flex-col">
                    {/* Auto lane ΓÇö above search + scroll so the default is always one click away. */}
                    {showAutoLane ? (
                        <>
                            <DropdownMenu aria-label={autoLaneLabel}>
                                <DropdownSection>
                                    <DropdownItem
                                        key="auto"
                                        textValue={autoLaneLabel}
                                        onPress={() => {
                                            onSelect({
                                                model: null,
                                                provider: null,
                                            })
                                            setIsOpen(false)
                                        }}
                                    >
                                        <div
                                            className={cn(
                                                "flex items-center gap-2",
                                                !selection.model && "text-accent-soft-foreground",
                                            )}
                                        >
                                            <SparkleIcon className="size-4 shrink-0" />
                                            <span>{autoLaneLabel}</span>
                                        </div>
                                    </DropdownItem>
                                </DropdownSection>
                                <Separator />
                            </DropdownMenu>
                        </>
                    ) : null}
                    {/* Search ΓåÆ inline tier filter ΓåÆ list, separated by whitespace only
                    (no divider, no funnel panel). down + off-task hidden by default. */}
                    <div
                        className="px-2"
                        onKeyDownCapture={(event) => event.stopPropagation()}
                    >
                        <SearchField
                            variant="secondary"
                            aria-label={searchModelLabel}
                        >
                            <SearchField.Group>
                                <SearchField.SearchIcon />
                                <SearchField.Input
                                    placeholder={searchModelLabel}
                                    value={query}
                                    onChange={(event) => setQuery(event.target.value)}
                                />
                                {query ? (
                                    <SearchField.ClearButton onPress={() => setQuery("")} />
                                ) : null}
                            </SearchField.Group>
                        </SearchField>
                    </div>
                    {/* tier filter ΓÇö FlexWrapButtonRadio inside popover surface */}
                    {tierChips.length > 1 ? (
                        <div className="px-2 pt-2">
                            <FlexWrapButtonRadio
                                ariaLabel={filterTierLabel}
                                value={tierFilter}
                                onChange={setTierFilter}
                                items={tierChips.map((tier) => ({
                                    value: tier,
                                    content: tier === "all"
                                        ? filterAllLabel
                                        : tierLabels[tier],
                                }))}
                            />
                        </div>
                    ) : null}
                    <ScrollShadow
                        hideScrollBar
                        className="max-h-72 w-full min-w-0"
                    >
                        <DropdownMenu
                            aria-label={pickModelLabel}
                            className="w-full min-w-0"
                        >
                            {/* One entry per catalog model. Below-floor = warning (selectable,
                        risky); Balanced/Premium/Frontier = locked without an unlock. */}
                            <DropdownSection>
                                {visibleModels.length === 0 ? (
                                    <DropdownItem
                                        key="no-results"
                                        textValue={searchModelEmptyLabel}
                                        onPress={() => undefined}
                                    >
                                        <span className="text-muted">{searchModelEmptyLabel}</span>
                                    </DropdownItem>
                                ) : null}
                                {visibleModels.map((model) => {
                                    const key = `${model.provider}:${model.model}`
                                    const isSelected = selection.model === model.model
                                        && selection.provider === model.provider
                                    const categoryChip = <AiCategoryChip category={model.category} />
                                    // live health (right of the category chip); null until probe data arrives
                                    const health = latency.get(model.model)
                                    const healthChip = health
                                        ? (
                                            <ModelHealthChip
                                                ok={health.ok}
                                                latencyMs={health.latencyMs}
                                                errorMessage={health.errorMessage}
                                                latencyLabel={latencyLabel(health.latencyMs)}
                                                downLabel={downLabel}
                                            />
                                        )
                                        : null
                                    const selfHostMark = showSelfHostMark(model) ? <SelfHostGpuMark /> : null
                                    const requiresPlan = PLAN_CATEGORIES.includes(model.category)
                                    // below the recommended floor ΓåÆ flag danger (grading: Free is
                                    // below Economy). No floor ΓåÆ never flagged (chatbot runs Free).
                                    const belowFloor = floor !== undefined
                                        && CATEGORY_ORDER.indexOf(model.category) < CATEGORY_ORDER.indexOf(floor)
                                    // not suited for this picker's task ΓåÆ amber warning
                                    const offTask = Boolean(task
                                        && model.supportedTasks?.length
                                        && !model.supportedTasks.includes(task))
                                    if (!model.available) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => undefined}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningCircleIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>{modelUnavailableLabel}</Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (requiresPlan && !canPremium) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={onUpgrade}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            muted
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<LockIcon className="size-5 shrink-0" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm">{subscribeToGradeLabel}</Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    if (belowFloor || offTask) {
                                        return (
                                            <DropdownItem
                                                key={key}
                                                textValue={model.model}
                                                className={DROPDOWN_ITEM_ROW_CLASS}
                                                onPress={() => onSelect({
                                                    model: model.model,
                                                    provider: model.provider,
                                                })}
                                            >
                                                <Tooltip>
                                                    <Tooltip.Trigger className={MODEL_ROW_TRIGGER_CLASS}>
                                                        <ModelRowLayout
                                                            isSelected={isSelected}
                                                            name={model.model}
                                                            nameSuffix={selfHostMark}
                                                            leading={<WarningIcon className="size-5 shrink-0 text-warning-soft-foreground" />}
                                                            trailing={<>{healthChip}{categoryChip}</>}
                                                        />
                                                    </Tooltip.Trigger>
                                                    <Tooltip.Content>
                                                        <Typography type="body-sm" className="text-warning-soft-foreground">
                                                            {belowFloor
                                                                ? belowFloorWarningLabel
                                                                : offTaskWarningLabel}
                                                        </Typography>
                                                    </Tooltip.Content>
                                                </Tooltip>
                                            </DropdownItem>
                                        )
                                    }
                                    return (
                                        <DropdownItem
                                            key={key}
                                            textValue={model.model}
                                            className={DROPDOWN_ITEM_ROW_CLASS}
                                            onPress={() => onSelect({
                                                model: model.model,
                                                provider: model.provider,
                                            })}
                                        >
                                            <ModelRowLayout
                                                isSelected={isSelected}
                                                name={model.model}
                                                nameSuffix={selfHostMark}
                                                trailing={<>{healthChip}{categoryChip}</>}
                                            />
                                        </DropdownItem>
                                    )
                                })}
                            </DropdownSection>
                        </DropdownMenu>
                    </ScrollShadow>
                    {/* escape hatch ΓÇö reveal the down / off-task models hidden by default */}
                    {hiddenCount > 0 ? (
                        <button
                            type="button"
                            onClick={() => setShowHidden((open) => !open)}
                            className="cursor-pointer px-3 pb-2 pt-1 text-start text-xs text-muted transition-colors hover:text-foreground"
                        >
                            {showHidden
                                ? hideHiddenModelsLabel
                                : showHiddenModelsLabel(hiddenCount)}
                        </button>
                    ) : null}
                </div>
            </DropdownPopover>
        </Dropdown>
    )
}

