} from "react"
import {
    Background,
    BackgroundVariant,
    Controls,
    Handle,
    MiniMap,
    Position,
    ReactFlow,
    ReactFlowProvider,
    useReactFlow,
    useStore,
    type NodeProps,
    type NodeTypes,
} from "@xyflow/react"
import {
    Typography,
    cn,
} from "@heroui/react"
import { useAppSelector } from "@/redux/hooks"
import type {
    CourseMindMapData,
    CourseMindMapNodeData,
} from "@/modules/api/graphql/queries/types"
import type { MindMapRailTier as MindMapTier } from "@/components/blocks/learn/MindMapRail"
