import type { WithClassNames } from "@/modules/types/base/class-name"

/** Border-ring tone per popularity tier (green / yellow / red) ΓÇö the ring signals how common a keyword is. */
const RING_BY_POP: Record<string, string> = {
    high: "border-success",
    medium: "border-warning",
    low: "border-danger",
}
/** MiniMap swatch colour per tier (SVG fill wants a concrete colour, not a utility class). */
const MINIMAP_BY_POP: Record<string, string> = {
    high: "#2f8f57",
    medium: "#c99a1e",
    low: "#c0392b",
}

/**
 * One authored KEYWORD ΓÇö a card whose RING colour encodes its popularity tier (green = very common,
 * yellow = common, red = specialized). The face carries ONLY the keyword; the explainer + related
 * surfaces (via RAG) live in the drawer that opens on click.
 */
const ConceptNode = ({ data, selected }: NodeProps) => {
    const node = data as unknown as CourseMindMapNodeData
    const ring = (node.popularity && RING_BY_POP[node.popularity]) || "border-default"
    return (
        <div
            className={cn(
                "max-w-[220px] rounded-2xl border-2 bg-surface px-3.5 py-2 shadow-surface transition-shadow hover:shadow-md",
                selected ? "border-accent" : ring,
            )}
        >
            <Handle type="target" position={Position.Left} className="!size-2 !border-0 !bg-transparent !opacity-0" />
            <Typography type="body-sm" weight="medium" className="line-clamp-2">
                {node.label}
            </Typography>
            <Handle type="source" position={Position.Right} className="!size-2 !border-0 !bg-transparent !opacity-0" />
        </div>
    )
}

/** The course root ΓÇö the trunk every branch hangs off. */
const RootNode = ({ data }: NodeProps) => {
    const node = data as unknown as CourseMindMapNodeData
    return (
        <div className="max-w-[220px] rounded-2xl bg-accent px-4 py-3 text-center shadow-surface">
            <Typography type="body-sm" weight="bold" className="text-accent-foreground line-clamp-2">
                {node.label}
            </Typography>
            <Handle type="source" position={Position.Right} className="!size-2 !border-0 !bg-transparent !opacity-0" />
        </div>
    )
}

/** Stable map ΓÇö React Flow re-mounts every node when this identity changes. */
const nodeTypes: NodeTypes = {
    concept: ConceptNode,
    course: RootNode,
}

/** Half a node's box ΓÇö `setCenter` wants the node CENTRE, positions are the top-left corner. */
const NODE_HALF_W = 110
const NODE_HALF_H = 20

/** Left margin (px) the course root is pinned to on the initial frame. */
const INITIAL_LEFT = 72
/** Readable-but-dense zoom the map opens at (small enough to show many, big enough to read). */
const INITIAL_ZOOM = 0.8

/**
 * Frames the map ONCE per mount: the course root pinned near the LEFT edge, vertically centred, at
 * a readable zoom ΓÇö so it opens the same way on every mount / F5 / re-mount (teacher 2026-07-18: "render
 * close to the course ┬╖ course name flush left ┬╖ small enough to render many, big enough to read"). Not `fitView` (which
 * centres the whole tree's bbox ΓåÆ an empty middle). Must live INSIDE the flow.
 */
const InitialFrame = ({
    nodes,
}: InitialFrameProps) => {
    const { setViewport } = useReactFlow()
    const paneHeight = useStore((state) => state.height)
    const framed = useRef(false)
    useEffect(() => {
        if (framed.current || !paneHeight) {
            return
        }
        const root = nodes.find((candidate) => candidate.type === "course")
        if (!root) {
            return
        }
        framed.current = true
        void setViewport(
            {
                // root.x is 0 (column 0) ΓåÆ screen x = INITIAL_LEFT; y translated so root sits centred.
                x: INITIAL_LEFT,
                y: paneHeight / 2 - root.position.y * INITIAL_ZOOM,
                zoom: INITIAL_ZOOM,
            },
            { duration: 0 },
        )
    }, [paneHeight, nodes, setViewport])
    return null
}

/** Recentres the viewport on the selected node whenever it changes (must live INSIDE the flow). */
const FocusOnSelect = ({
    selectedId,
    nodes,
}: FocusOnSelectProps) => {
    const { setCenter } = useReactFlow()
    useEffect(() => {
        if (!selectedId) {
            return
        }
        const node = nodes.find((candidate) => candidate.id === selectedId)
        if (node) {
            void setCenter(node.position.x + NODE_HALF_W, node.position.y + NODE_HALF_H, {
                zoom: 0.9,
                duration: 600,
            })
        }
    }, [selectedId, nodes, setCenter])
    return null
}

/** Props for {@link ConceptMap}. */
export interface ConceptMapProps extends WithClassNames<undefined> {
    /** The full keyword graph (server-laid-out). */
    data: CourseMindMapData
    /** Live search text ΓÇö hides non-matching nodes (keeping matches + their ancestor path). */
    query: string
    /** Popularity floor ΓÇö dims lower tiers while browsing (no search). */
    tier: MindMapTier
    /** The node whose drawer is open + which the view is centred on (`null` = none). */
    selectedId: string | null
    /** Select a node (open its drawer + recentre) ΓÇö `null` closes. */
    onSelectId: (id: string | null) => void
}

/**
 * The keyword-map CANVAS (controlled) ΓÇö React Flow over the server's tidy-tree positions. Ring
 * colour = popularity; clicking a node (or a rail result) selects it ΓåÆ the view recentres
 * (`FocusOnSelect`) and its drawer (explainer + RAG surfaces) opens. Search HIDES non-matching
 * nodes but keeps each match's ancestor path so it never floats context-free; the tier filter dims
 * lower tiers while browsing. Filter + selection state is owned by the parent workspace.
 *
 * @param props - {@link ConceptMapProps}
 */
export const ConceptMap = ({
    data,
    query,
    tier,
    selectedId,
    onSelectId,
    className,
}: ConceptMapProps) => {
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)

    // when searching, the VISIBLE set = every match + its ancestor path + the root (so a matched
    // node never floats without its branch). `null` = no search ΓåÆ nothing hidden.
    const visible = useMemo(
        () => {
            const value = query.trim().toLowerCase()
            if (!value) {
                return null
            }
            const parentOf = new Map(data.edges.map((edge) => [edge.target, edge.source]))
            const set = new Set<string>()
            for (const node of data.nodes) {
                const nodeData = node.data as unknown as CourseMindMapNodeData
                if (node.type === "course") {
                    set.add(node.id)
                    continue
                }
                const matches = String(nodeData.label).toLowerCase().includes(value)
                    && tierAllows(nodeData.popularity, tier)
                if (matches) {
                    let cursor: string | undefined = node.id
                    while (cursor) {
                        set.add(cursor)
                        cursor = parentOf.get(cursor)
                    }
                }
            }
            return set
        },
        [query, tier, data],
    )

    const nodes = useMemo(
        () => data.nodes.map((node) => {
            const pop = (node.data as unknown as CourseMindMapNodeData).popularity
            // browsing (no search): dim tiers below the floor; searching: hide non-visible nodes.
            const dimmed = !visible && node.type !== "course" && pop
                ? POP_RANK[pop] < TIER_MIN[tier]
                : false
            return {
                id: node.id,
                type: node.type ?? "concept",
                position: node.position,
                data: node.data as unknown as Record<string, unknown>,
                selected: node.id === selectedId,
                hidden: visible ? !visible.has(node.id) : false,
                className: dimmed ? "opacity-15 transition-opacity" : "transition-opacity",
            }
        }),
        [data, tier, visible, selectedId],
    )
    const edges = useMemo(
        () => data.edges.map((edge) => ({
            id: edge.id,
            source: edge.source,
            target: edge.target,
            // bezier curves ("rounded line") read smoother than orthogonal steps.
            type: "default",
        })),
        [data],
    )

    const selectedData = selectedId
        ? (data.nodes.find((node) => node.id === selectedId)?.data as unknown as CourseMindMapNodeData | undefined)
        : undefined

    return (
        <div className={cn("relative h-full w-full", className)}>
            <ReactFlowProvider>
                <ReactFlow
                    nodes={nodes}
                    edges={edges}
                    nodeTypes={nodeTypes}
                    minZoom={0.1}
                    nodesDraggable={false}
                    nodesConnectable={false}
                    proOptions={{
                        hideAttribution: true,
                    }}
                    onNodeClick={(_event, node) => {
                        // root re-frames (deselect); every keyword selects ΓåÆ recentre + drawer.
                        onSelectId(node.type === "course" ? null : node.id)
                    }}
                    onPaneClick={() => onSelectId(null)}
                >
                    <Background variant={BackgroundVariant.Dots} gap={22} size={1} />
                    <Controls showInteractive={false} />
                    <MiniMap
                        pannable
                        zoomable
                        nodeColor={(node) => (node.type === "course"
                            ? "#c0407a"
                            : MINIMAP_BY_POP[String((node.data as unknown as CourseMindMapNodeData).popularity)] ?? "#c0c0c8")}
                    />
                    <InitialFrame nodes={data.nodes} />
                    <FocusOnSelect selectedId={selectedId} nodes={data.nodes} />
                </ReactFlow>
            </ReactFlowProvider>

            <MindMapNodeDrawer
                keyword={selectedData?.label ?? null}
                desc={selectedData?.desc ?? null}
                courseId={courseId ?? null}
                courseDisplayId={displayId ?? null}
                isOpen={Boolean(selectedId)}
                onClose={() => onSelectId(null)}
            />
        </div>
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `ContentCommentComposer`: the textarea + submit control for new
 * comments, replies, and edits ΓÇö ONE component, three call shapes, ported
 * verbatim from real `src`'s `CommentComposer`. See the component's own file
 * header for why `variant="primary"` (real `Discussion` is frameless ΓÇö no
 * card ever wraps this field) and why the avatar-led row is top-level only.
 *
 * LEAVES by STRUCTURE (┬º14d.2). Collapsed-pill vs expanded-field is a real
 * node swap => separate leaves. Avatar present/absent is also a node swap
 * (top-level vs reply/edit) => its own leaf.
 */

/** Minimal identity for the avatar-led top-level composer. */
export interface ContentCommentComposerViewer {
    username: string
    avatarUrl?: string
}

/** Props for {@link ContentCommentComposer}. */
export interface ContentCommentComposerProps {
    /** Called with the trimmed body when the reader submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the field. */
    placeholder?: string
    /** Submit button label. */
    submitLabel?: string
    /** Optional cancel handler ΓÇö renders a cancel button when provided (reply/edit). */
    onCancel?: () => void
    /** Initial field value (editing an existing comment). */
    initialValue?: string
    /** `true` -> submit is disabled and shows its busy affordance. */
    isPending?: boolean
    /**
 * Set -> the composer is avatar-led (top-level only; reply/edit omit this).
 * `null` -> signed-out top-level composer, no avatar.
 */
    currentUser?: ContentCommentComposerViewer | null
    /**
 * `true` -> starts collapsed as a slim avatar + placeholder pill, expands to
 * the full field on click (the top-level composer pattern). Reply/edit
 * composers omit this and render expanded.
 */
    collapsible?: boolean
    /** Accessible name for the field. */
    ariaLabel: string
    /** Where this sits inside its parent (placement only, e.g. `flex-1` beside a `ThreadConnector`). */
    classNames?: Array<AllowedClassName>
}

/**
 * The comment/reply/edit composer. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentComposerProps}
 */
const ContentCommentComposer = ({
    onSubmit: onSubmitAction,
    placeholder = "Ask a question or share your thoughtsΓÇª",
    submitLabel = "Post",
    onCancel: onCancelAction,
    initialValue,
    isPending = false,
    currentUser,
    collapsible = false,
    ariaLabel,
    classNames,
}: ContentCommentComposerProps) => {
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; reply/edit always render expanded
    const [expanded, setExpanded] = useState(!collapsible)
    const trimmed = body.trim()

    const onSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmitAction(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <StackH identity={{ tier: "block", component: "ContentCommentComposer" }}
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"

                items={[
                    ...(currentUser ? [() => (
                        <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
                    )] : []),
                    () => (
                        <div className="min-w-0 flex-1">
                            <InputButtonLike
                                placeholder={placeholder}
                                ariaLabel={ariaLabel}
                                onPress={() => setExpanded(true)}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const buttonRow = (
        <>
            <Button
                label={submitLabel}
                size="sm"
                onPress={onSubmit}
                isDisabled={!trimmed}
                isPending={isPending}

            />
            {onCancel || collapsible ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}

                />
            ) : null}
        </>
    )

    const fieldColumn = (
        <>
            <InputTextarea
                value={body}
                onValueChange={setBody}
                placeholder={placeholder}
                ariaLabel={ariaLabel}
                rows={3}
                variant="primary"

            />
            <StackH gap={3} items={[() => buttonRow]} />
        </>
    )

    const composerRow = (
        <>
            {currentUser ? (
                <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
            ) : null}
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => fieldColumn]} />
        </>
    )

    return (
        <StackH identity={{ tier: "block", component: "ContentCommentComposer" }} gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start" classNames={classNames} items={[() => composerRow]}  />
    )
}

export { ContentCommentComposer }

import React from "react"
import { ChatsCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ContentCommentThread, type ContentCommentNode, type ContentCommentThreadCallbacks } from "@/components/blocks/learn/ContentCommentThread"

/**
 * `ContentDiscussion` ΓÇö talk about this lesson: a label + archive line, an
 * avatar-led collapsible composer, and the threaded comment list, frameless on
 * the page canvas. The empty state is drawn on purpose ΓÇö no comments yet is an
 * invitation. The composer never hides, and an error replaces the list only.
 * Comment count, archive line, and `hasMore` are states of `Full`; empty, error,
 * and the loading mirror are each their own leaf.
 */

/** Props for {@link ContentDiscussion}. */
export interface ContentDiscussionProps extends ContentCommentThreadCallbacks {
    /** Section label, localized by the caller ΓÇö e.g. "Discussion" (the block appends "┬╖ {total}"). */
    label: string
    /** Current viewer id ΓÇö drives owner-only edit/delete down the whole tree; null when signed out. */
    currentUserId: string | null
    /** Current viewer identity for the composer's avatar; null when signed out. */
    currentUser?: ContentCommentComposerViewer | null
    /** Top-level comments, newest first. EMPTY -> the invitation is drawn instead. */
    comments: Array<ContentCommentNode>
    /** Total top-level comment count (drives the label + the archive line). */
    total: number
    /** Replies keyed by parent comment id (lazily populated by the caller). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** `true` -> more top-level comment pages remain to load. */
    hasMore?: boolean
    /** `true` -> the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
    /**
 * Set -> the comment list could not be loaded. The message replaces the
 * LIST only: the composer stays, because a failed read did not remove
 * the ability to write.
 */
    errorMessage?: string
    /** `true` -> two placeholder threads mirror the real row shape while the first page loads. */
    isSkeleton?: boolean
}

/** Two placeholder rows so the mirror has the same shape as a short thread. */
const SKELETON_ROWS: Array<ContentCommentNode> = [
    { id: "s1", author: { id: "s1", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
    { id: "s2", author: { id: "s2", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
]

/**
 * Lesson discussion. See the file header for the full contract.
 *
 * @param props - {@link ContentDiscussionProps}
 */
const ContentDiscussion = ({
    label,
    currentUserId,
    currentUser,
    comments,
    total,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore = false,
    isLoadingMore = false,
    onLoadMore,
    errorMessage,
    isSkeleton = false,
}: ContentDiscussionProps) => {
    // real (not fabricated) count of currently-loaded top-level comments that already
    // have at least one reply ΓÇö under-counts before "load more" is exhausted, same
    // tradeoff real `Discussion` documents for its own archive line
    const answeredCount = comments.filter((comment) => comment.replyCount > 0).length

    // no icon here: a chat-bubble icon needs an ASSOCIATION step to read as
    // "discussion" (not a universal symbol like [ok]/(locked)), and the label text already
    // carries the full fact on its own.
    const labelLines = (
        <>
            {isSkeleton ? (
                <Typography weight="medium" isSkeleton classNames={["w-1/4"]} />
            ) : (
                <Typography weight="medium" text={`${label} ┬╖ ${total}`} />
            )}
            {isSkeleton || total > 0 ? (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    classNames={isSkeleton ? ["w-2/3"] : undefined}
                    text={`${answeredCount}/${total} questions answered, accumulated over time`}

                />
            ) : null}
        </>
    )

    const discussionHeader = (
        <>
            <StackV gap={2} isSkeleton={isSkeleton} items={[() => labelLines]} />
            <ContentCommentComposer
                onSubmit={onSubmitComment}
                currentUser={currentUser}
                collapsible
                ariaLabel="Write a comment"


            />
        </>
    )

    const commentList = (
        <>
            {(isSkeleton ? SKELETON_ROWS : comments).map((comment) => (
                <ContentCommentThread
                    key={comment.id}
                    comment={comment}
                    currentUserId={currentUserId}
                    currentUser={currentUser}
                    depth={0}
                    repliesByParent={repliesByParent}
                    onReply={onReply}
                    onEdit={onEdit}
                    onDelete={onDelete}
                    onReactComment={onReactComment}
                    onLoadReplies={onLoadReplies}

                />
            ))}
            {!isSkeleton && hasMore ? (
                <Button
                    variant="ghost"
                    size="sm"
                    classNames={["self-center"]}
                    label={isLoadingMore ? "LoadingΓÇª" : "Show more comments"}
                    isDisabled={isLoadingMore}
                    onPress={onLoadMore}
                />
            ) : null}
        </>
    )

    const discussionBody = (
        <>
            {/* These 3 seams match the real-src `Discussion/index.tsx:98-114` exactly:
 [label+archive]<->composer = grouped (gap-3) ┬╖ [icon+label]<->archive-line
 = tight (gap-1) ┬╖ icon<->label = related (gap-2). */}
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionHeader]} />

            {errorMessage != null ? (
                <EmptyState
                    icon={WarningCircleIcon}
                    title={errorMessage}

                />
            ) : !isSkeleton && comments.length === 0 ? (
                // Nobody has written yet. This is an INVITATION, so it is drawn ΓÇö
                // hiding the section would hide the invitation with it.
                <EmptyState
                    icon={ChatsCircleIcon}
                    title="No discussion yet"
                    description="Ask the first question about this lesson"

                />
            ) : (
                <StackV gap={4} isSkeleton={isSkeleton} items={[() => commentList]} />
            )}
        </>
    )

    return (
        <div>
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionBody]} />
        </div>
    )
}

export { ContentDiscussion }

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `CourseQaComposer`: the ONE writing shape reused three ways on a
 * course Q&A board ΓÇö the root "ask the whole course" collapsible pill, an
 * answer's inline edit form, and an inline reply form. See the component file
 * header for the full mode/`initialValue`/fold-back contract and why this is
 * genuinely new rather than a duplicate of `_legacy/blocks/feed/Composer`.
 */

/** Which of the block's two writing shapes to render. */
export type CourseQaComposerMode = "collapsible" | "plain"

/** The signed-in viewer writing this ΓÇö plain data, the block builds the avatar from it. */
export interface CourseQaComposerUser {
    /** Display name; also seeds the avatar's initials fallback. */
    name: string
    /** Avatar image URL. Omitted ΓåÆ the avatar falls back per its own chain. */
    avatarSrc?: string
}

/** Props for {@link CourseQaComposer}. */
export interface CourseQaComposerProps {
    /**
     * `"collapsible"` ΓÇö boots as a slim avatar + placeholder pill, opens into the
     * full form on press (the root "ask the whole course" composer). `"plain"` ΓÇö
     * always the full form (an answer's inline edit, an inline reply, or a
     * bottom "write an answer" box).
     */
    mode: CourseQaComposerMode
    /** The signed-in viewer. Omitted ΓåÆ no leading avatar is drawn (either shape). */
    currentUser?: CourseQaComposerUser
    /**
     * Existing content this composer opened WITH (an edit/reply reopened, not a
     * fresh draft). Read once, only to decide a `"collapsible"` composer's BOOT
     * state ΓÇö see the file header. Never re-consulted after mount; the live
     * draft is entirely `value`/`onValueChange`.
     */
    initialValue?: string
    /** The current draft text ΓÇö fully controlled by the caller. */
    value: string
    /** Fired with the next draft text on every keystroke. */
    onValueChange: (value: string) => void
    /** Placeholder for both the collapsed pill and the open textarea. */
    placeholder?: string
    /** Label for the submit button. Defaults to `"Send"`. */
    submitLabel?: string
    /**
     * Fired when the viewer submits. The caller already holds the draft via
     * `value`, so this fires with no argument. A `"collapsible"` composer folds
     * itself back to the pill right after ΓÇö the caller is still responsible for
     * clearing `value`.
     */
    onSubmit: () => void
    /**
     * Fired when the viewer backs out. Shown whenever `mode === "collapsible"`
     * (folding back to the pill always needs a way out) or whenever the caller
     * supplies this (the edit/reply shapes of `mode === "plain"`).
     */
    onCancel?: () => void
    /** `true` ΓåÆ submit is in flight: the Submit button owns the busy affordance and both buttons lock. */
    isPending?: boolean
    /**
     * `true` ΓåÆ every composed atom mirrors itself. The flag FLOWS DOWN into the
     * real atoms (┬º12c) rather than a parallel skeleton tree, within whichever
     * leaf (`CollapsedPrompt`/`ExpandedForm`) is currently showing.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's one writing shape. See the file header for the mode
 * contract, the controlled-text/`initialValue` split, and the fold-back
 * judgement call.
 *
 * @param props - {@link CourseQaComposerProps}
 */
const CourseQaComposer = ({
    mode,
    currentUser,
    initialValue,
    value,
    onValueChange,
    placeholder,
    submitLabel = "Send",
    onSubmit: onSubmitAction,
    onCancel: onCancelAction,
    isPending = false,
    isSkeleton = false,
}: CourseQaComposerProps) => {
    // Transient UI-only chrome (┬º not domain data) ΓÇö owned here, never lifted to
    // the caller. A "plain" composer has no collapsed shape at all, so it always
    // boots open; a "collapsible" one boots open only when reopened WITH content.
    const [expanded, setExpanded] = useState(() => mode === "plain" || Boolean(initialValue))

    const canSubmit = value.trim().length > 0 && !isPending
    const showCancel = mode === "collapsible" || onCancel != null

    const onSubmit = () => {
        onSubmitAction()
        // Folding back is presentational chrome the block owns; the caller still
        // clears `value` itself (it owns the draft) ΓÇö see file header.
        if (mode === "collapsible") {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        if (mode === "collapsible") {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    const avatar = currentUser || isSkeleton ? (
        <Avatar
            name={currentUser?.name}
            src={currentUser?.avatarSrc}
            size="sm"
            isSkeleton={isSkeleton}
            classNames={["shrink-0"]}

        />
    ) : null

    // ΓöÇΓöÇ LEAF ΓÇö CollapsedPrompt: avatar + pill, nothing else composed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (mode === "collapsible" && !expanded) {
        return (
            <div>
                <StackH
                    gap={3}
                    isSkeleton={isSkeleton}
                    items={[
                        () => avatar,
                        () => (
                            <div className="min-w-0 flex-1">
                                <InputButtonLike
                                    placeholder={placeholder ?? "Ask a question about this courseΓÇª"}
                                    onPress={() => setExpanded(true)}
                                    isSkeleton={isSkeleton}
                                />
                            </div>
                        ),
                    ]}
                />
            </div>
        )
    }

    // ΓöÇΓöÇ LEAF ΓÇö ExpandedForm: avatar + textarea + action row ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const actionRow = (
        <>
            {showCancel ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}
                    isSkeleton={isSkeleton}

                />
            ) : null}
            <Button
                label={submitLabel}
                variant="primary"
                size="sm"
                onPress={onSubmit}
                isDisabled={!canSubmit}
                isPending={isPending}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const form = (
        <>
            <InputTextarea
                value={value}
                onValueChange={onValueChange}
                placeholder={placeholder}
                ariaLabel={placeholder ?? "Content"}
                rows={3}
                isDisabled={isPending}
                isSkeleton={isSkeleton}

            />
            <StackH gap={3} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="end" isSkeleton={isSkeleton} items={[() => actionRow]}  />
        </>
    )

    return (
        <div>
            <StackH
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => avatar,
                    ({ isSkeleton }: SkeletonProps) => <StackV gap={3} isSkeleton={isSkeleton} classNames={["min-w-0", "flex-1"]} items={[() => form]} />,
                ]}
            />
        </div>
    )
}

