import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CheckIcon, CircleIcon, LockIcon, PlayIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@/components/blocks/learn/VariantChip"

/**
 * `ModuleLessonList` ΓÇö the full, ordered lesson table of contents for one module ΓÇö
 * every lesson, not just what's next. Sibling of `KeepGoingPath` (which trims to
 * the continue-learning queue and owns a heading); this block takes no heading of
 * its own. The block owns the per-row status icon (`resume`/`read`/`unread`), the
 * "N min read ┬╖ M challenges" subtitle, and whether a difficulty chip and premium
 * lock ride on the trailing side. Row-level differences are states of one
 * `SurfaceCardList` tree; `isSkeleton` is its own leaf.
 */

/** Where this lesson sits in the reader's progress through the module. */
type LessonStatus = "resume" | "read" | "unread"

/** One lesson row ΓÇö plain data; the block assembles the wording and the icon. */
export interface ModuleLessonListLesson {
    /** Stable id ΓÇö also what `onSelectLesson`/`resumeLessonId` key off. */
    id: string
    /** Lesson title. */
    title: string
    /** Reading time in minutes ΓÇö the block folds this into the subtitle itself. */
    minutesRead: number
    /** Practice-challenge count for this lesson ΓÇö folded into the same subtitle. */
    challengeCount: number
    /** Already finished at least once. */
    isRead: boolean
    /** Behind the paid tier ΓÇö shows the trailing lock marker. */
    isPremium: boolean
    /** Difficulty tier ΓÇö the block builds `VariantChipDifficulty` itself. Omit -> no chip. */
    difficulty?: Difficulty
}

/** Props for {@link ModuleLessonList}. */
export interface ModuleLessonListProps {
    /** Every lesson in the module, in reading order. */
    lessons: Array<ModuleLessonListLesson>
    /** The lesson to mark "resume" ΓÇö wins over `isRead` for the leading icon (see file header). */
    resumeLessonId?: string
    /** Fired with the lesson id on ANY row press, premium or not (see the NO note above). */
    onSelectLesson: (id: string) => void
    /**
 * `true` -> the list draws its own row mirror. `lessons` empty while loading
 * (┬º12c) -> guesses 3 rows, the SSOT convention this composite's siblings
 * (`KeepGoingPath`, `LearnNudges`) already use.
 */
    isSkeleton?: boolean
}

/** Resolves the leading-icon state: `resumeLessonId` wins over `isRead` (see file header). */
const lessonStatus = (lesson: ModuleLessonListLesson, resumeLessonId?: string): LessonStatus => {
    if (resumeLessonId != null && lesson.id === resumeLessonId) {
        return "resume"
    }
    return lesson.isRead ? "read" : "unread"
}

/** The leading mark one lesson status resolves to: which glyph, and how it is coloured. */
interface LessonLeadingStyle {
    /** Phosphor glyph component for this status. */
    Icon: typeof CircleIcon
    /** Size + colour classes. */
    className: string
}

/** Leading glyph + colour per status ΓÇö the block owns this table, the caller never picks an icon. */
const STATUS_LEADING: Record<LessonStatus, LessonLeadingStyle> = {
    resume: { Icon: PlayIcon, className: "size-5 text-accent-soft-foreground" },
    read: { Icon: CheckIcon, className: "size-5 text-success-soft-foreground" },
    unread: { Icon: CircleIcon, className: "size-5 text-foreground" },
}

/** Placeholder rows for the guessed skeleton count (┬º12c) ΓÇö never carry a press handler. */
const SKELETON_LESSONS: Array<ModuleLessonListLesson> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    minutesRead: 0,
    challengeCount: 0,
    isRead: false,
    isPremium: false,
    difficulty: "beginner",
}))

/**
 * The module's full lesson table of contents. See the file header for the full
 * contract and the two judgement calls that set it apart from `KeepGoingPath`.
 *
 * @param props - {@link ModuleLessonListProps}
 */
const ModuleLessonList = ({
    lessons,
    resumeLessonId,
    onSelectLesson,
    isSkeleton = false,
}: ModuleLessonListProps) => {
    // Empty while loading (no real lessons yet) -> guess 3 rows, keeping the right
    // shape for when real data arrives (┬º8). Once real `lessons` exist, keep the
    // EXACT row count already there ΓÇö the placeholder set never mixes with real rows.
    const usingPlaceholders = isSkeleton && lessons.length === 0
    const source = usingPlaceholders ? SKELETON_LESSONS : lessons

    const rows: Array<SurfaceCardListItem> = source.map((lesson) => {
        const { Icon, className } = STATUS_LEADING[lessonStatus(lesson, resumeLessonId)]
        return {
            key: lesson.id,
            leading: () => (isSkeleton ? (
                // The status icon is chosen DIRECTLY by the block from `STATUS_LEADING`,
                // never through an atom in between ΓÇö hand-roll a single shimmer dot in
                // its place instead of branching off to build a whole separate row (┬º12c).
                <Skeleton className="size-5 shrink-0 rounded-full" />
            ) : (
                <Icon aria-hidden focusable="false" className={className} />
            )),
            title: lesson.title,
            // The subtitle sentence is assembled HERE ΓÇö the caller hands over two
            // numbers, never a pre-formatted string (┬º14d.1).
            subtitle: `${lesson.minutesRead} min read ┬╖ ${lesson.challengeCount} challenges`,
            // Placeholder rows never become press targets ΓÇö nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectLesson(lesson.id),
            // Difficulty is DESIGN's shape (`VariantChipDifficulty`, ┬º14d.1) ΓÇö the block
            // doesn't reshape the chip, only decides whether one is offered at all.
            meta: lesson.difficulty != null ? () => (
                <VariantChipDifficulty
                    difficulty={lesson.difficulty!}
                    isSkeleton={isSkeleton}

                />
            ) : undefined,
            // A quiet trailing marker, riding NEXT TO the chip rather than replacing the
            // leading icon (see the * judgement call above).
            trailingIcon: lesson.isPremium ? LockIcon : undefined,
        }
    })

    return (
        <SurfaceCardList identity={{ tier: "block", component: "ModuleLessonList" }}

            isSkeleton={isSkeleton}
            items={rows}
        />
    )
}

export { ModuleLessonList }

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { TabsExtended } from "@/components/atoms/navigation/Tabs"
import { Button } from "@/components/atoms/buttons/Button"
import { Callout } from "@/components/composites/feedback/Callout"
import { ConfirmDialog } from "@/components/composites/feedback/ConfirmDialog"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK ΓÇö `PlaygroundSetupSteps`: the ordered setup guide for a playground ΓÇö pair
 * the local agent, install the engine (an OS-tabbed guide), and ΓÇö Ollama flavor
 * only ΓÇö pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (┬º14d.2 ΓÇö see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs ΓÇö the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render ΓÇö named per ┬º"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model ΓÇö see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status ΓåÆ chip label/color ΓÇö fixed Vietnamese copy this block owns (┬º14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const onRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const onConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) ΓÇö built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={onRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired ΓÇö get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine ΓÇö skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id ΓÇö this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine ΓÇö once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh ΓÇö ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding ΓÇö ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use ΓÇö the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again ΓÇö Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return ΓÇö a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection ΓÇö getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={onConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

export { PlaygroundSetupSteps }

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Button as HeroButton, Popover as HeroPopover } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { ReactionPicker } from "@/components/atoms/feedback/ReactionPicker"
import { StackH } from "@/components/frames/Stack"
import { ReactionGlyph } from "./ReactionGlyph"
import { REACTION_BY_TYPE, type ReactionButtonProps, type ReactionType } from "./types"

export type { ReactionType, ReactionCount, ReactionButtonProps } from "./types"

/**
 * BLOCK ΓÇö `ReactionButton`: the Facebook-style six-emotion reaction control ΓÇö
 * pill trigger + Popover picker + compact summary. Shared verbatim between
 * `ContentReaction` (the lesson-level reaction) and each comment row in
 * `ContentDiscussion`'s thread ΓÇö the SAME control real `src`'s `ReactionBar`
 * is, reused between `InteractionBar` and `CommentItem`.
 *
 * LEAF by STRUCTURE (┬º14d.2). Which emotion is picked and whether the
 * summary is empty keep the same two-part shape => states. The caller
 * flipping `isSkeleton` is its own leaf.
 */

/**
 * The reaction trigger + picker + summary. See the file header for the full contract.
 *
 * @param props - {@link ReactionButtonProps}
 */
const ReactionButton = ({
    myReaction = null,
    counts = [],
    onReact,
    isPending = false,
    isSkeleton = false,
}: ReactionButtonProps) => {
    // controlled so the popover closes as soon as an emotion is picked ΓÇö mirrors real ReactionBar
    const [isOpen, setIsOpen] = useState(false)

    const total = counts.reduce((sum, entry) => sum + entry.count, 0)
    // busiest emotions first, top 3 ΓÇö same cap real ReactionBar uses for the stacked summary
    const topReactions = counts
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((entry) => REACTION_BY_TYPE[entry.type])

    const onPick = (type: ReactionType) => {
        setIsOpen(false)
        onReact(myReaction === type ? null : type)
    }

    if (isSkeleton) {
        return <span className="inline-block h-8 w-28 animate-pulse rounded-full bg-default" />
    }

    // compact summary: stacked top emojis + total ΓÇö dropped entirely at zero
    const summaryRow = total > 0 ? (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionGlyph key={reaction.type} type={reaction.type} size="sm" />
                        ))}
                    </span>
                ),
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" text={String(total)} />,
            ]}
        />
    ) : null

    const triggerAndSummary = (
        <>
            {/* trigger: opens the 6-emotion picker; shows the viewer's own pick once set */}
            <HeroPopover isOpen={isOpen} onOpenChange={setIsOpen}>
                <HeroPopover.Trigger>
                    <HeroButton
                        variant="tertiary"
                        isDisabled={isPending}
                        className="rounded-full"

                    >
                        <ReactionGlyph type={myReaction ?? "like"} size="sm" />
                        <span className="text-sm">
                            {myReaction ? REACTION_BY_TYPE[myReaction].label : "React"}
                        </span>
                    </HeroButton>
                </HeroPopover.Trigger>
                {/* TODO(atom): heavy skin-shape (rounded-full + px-2 py-1 pill) ΓÇö frame kh├┤ng l├ám ─æ╞░ß╗úc,
 tß║ím bß╗ìc bß║▒ng data-principle hand-set. `className` sits on `HeroPopover.Content`
 itself (the vendor's OWN rendered surface, react-aria `Popover`), not a raw <div>
 we author, so `Box` can't wrap it (moving the shape down onto an inner wrapping
 Box would leave the real popover surface with its default non-pill radius showing
 behind it ΓÇö a visible shape regression). `data-principle` on `Content` directly is
 type-safe (forwarded through `DOMAttributes`), so tagged in place instead. Needs a
 dedicated pill-popover atom/composite to own this shape. Same declared shape
 as `QaReactionBar.tsx`'s trigger.
 inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css. */}
                <HeroPopover.Content data-principle="pill-pad" className="overflow-visible rounded-full px-2 py-1">
                    <ReactionPicker
                        items={Object.values(REACTION_BY_TYPE).map((reaction) => ({ key: reaction.type, imgSrc: `/reactions/${reaction.type}.svg`, label: reaction.label }))}
                        activeKey={myReaction}
                        onSelect={(key) => onPick(key as ReactionType)}
                    />
                </HeroPopover.Content>
            </HeroPopover>

            {summaryRow}
        </>
    )

    return (
        <StackH gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center" isSkeleton={isSkeleton} items={[() => triggerAndSummary]}  />
    )
}

export { ReactionButton }

/** The six reactions, in the fixed display order real `src` uses. */
export type ReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** One reaction kind's fixed vocabulary ΓÇö the block's own table (┬º14d.1), never caller-supplied. */
interface ReactionDescriptor {
    type: ReactionType
    /** Native emoji glyph ΓÇö `alt` text for the real SVG asset. */
    emoji: string
    /** Accessible + summary label, matches `src/messages/vi.json`'s `discussion.reactions.*`. */
    label: string
}

/** Public export `REACTIONS` for this module. */
export const REACTIONS: ReadonlyArray<ReactionDescriptor> = [
    { type: "like", emoji: "≡ƒæì", label: "Like" },
    { type: "love", emoji: "Γ¥ñ∩╕Å", label: "Love" },
    { type: "haha", emoji: "≡ƒÿé", label: "Haha" },
    { type: "wow", emoji: "≡ƒÿ«", label: "Wow" },
    { type: "sad", emoji: "≡ƒÿó", label: "Sad" },
    { type: "angry", emoji: "≡ƒÿí", label: "Angry" },
]

/** Public export `REACTION_BY_TYPE` for this module. */
export const REACTION_BY_TYPE: Record<ReactionType, ReactionDescriptor> = REACTIONS.reduce(
    (acc, descriptor) => { acc[descriptor.type] = descriptor; return acc },
    {} as Record<ReactionType, ReactionDescriptor>,
)

/** How many times each reaction was picked ΓÇö one entry per emotion actually present. */
export interface ReactionCount {
    type: ReactionType
    count: number
}

/** Props for {@link ReactionButton}. */
export interface ReactionButtonProps {
    /** The viewer's own reaction, or `null`/omitted if they haven't reacted. */
    myReaction?: ReactionType | null
    /** Per-emotion counts. Empty/omitted ΓåÆ the summary is not drawn at all. */
    counts?: ReadonlyArray<ReactionCount>
    /** Fired with the picked emotion, or `null` to remove the current one. */
    onReact: (type: ReactionType | null) => void
    /** `true` ΓåÆ the reaction is in flight. The trigger owns the busy affordance. */
    isPending?: boolean
    /** `true` ΓåÆ the trigger + summary switch to their own shimmer. */
    isSkeleton?: boolean
}

import React from "react"
import type { ComponentType, ReactNode, SVGProps } from "react"
import { InfoIcon, LightbulbIcon, MapPinIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `SubmissionFindingsList` ΓÇö "Feedback": one accordion row per quality-gate finding
 * on a graded attempt ΓÇö severity icon + plain-text message (backtick code only) +
 * location chip in the trigger; type ErrorEmptyStateProps = { onRetry?: () => void; retryLabel?: string }

type PlainEmptyStateProps = { title: string }

markdown detail, a linked file location, and a
 * markdown suggestion in the panel. The frame is `SurfaceCard.Accordion` end to end;
 * the block supplies the domain (severity ΓåÆ icon/tone/sort-rank, the highΓåÆlow sort,
 * the repo-URL ΓåÆ file-link builder). Loading, empty, error, and populated are all
 * states of the one accordion card, routed through its own `isSkeleton`/`emptyState`
 * axes.
 */

/** Severity a finding carries ΓÇö drives the trigger icon/tone and the sort rank (high sorts first). */
export type SubmissionFeedbackSeverity = "high" | "medium" | "low"

/** An icon passed as a COMPONENT, rendered by this block at the size the text beside it uses. */
type SeverityIconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One severity's trigger icon + text tone + sort rank ΓÇö see {@link SEVERITY_VISUAL}. */
interface SeverityVisual {
    /** Trigger icon for this severity. */
    icon: SeverityIconComponent
    /** Tailwind text-color class for the icon (matches the severity's weight). */
    toneClassName: string
    /** Sort rank ΓÇö lower sorts first (high = 0). */
    rank: number
}

/**
 * Severity ΓåÆ trigger icon + text tone + sort rank. This is the block's own
 * domain vocabulary, never something a caller hands in.
 */
const SEVERITY_VISUAL: Record<SubmissionFeedbackSeverity, SeverityVisual> = {
    high: { icon: WarningCircleIcon, toneClassName: "text-danger", rank: 0 },
    medium: { icon: WarningCircleIcon, toneClassName: "text-warning", rank: 1 },
    low: { icon: InfoIcon, toneClassName: "text-muted", rank: 2 },
}

/** One quality-gate finding for a graded attempt. */
export interface SubmissionFinding {
    /** Stable id ΓÇö also the accordion row's expand key. */
    id: string
    /**
     * Short summary shown (clamped to one line) in the accordion trigger ΓÇö plain
     * text, at most `` `code` `` spans (never bold/italic/link: a trigger title
     * is tier 1). Full markdown
     * belongs in `detail`/`suggestion`, which render in the panel body instead.
     */
    message: string
    /** Longer explanation, authored as markdown, shown in the panel. */
    detail?: string
    /** Suggested fix, authored as markdown, shown in the panel. */
    suggestion?: string
    /** Repo-relative file path this finding points at, e.g. `src/app/page.tsx`. */
    location?: string
    /** High/medium/low ΓÇö decides the trigger icon/tone and the sort order. */
    severity: SubmissionFeedbackSeverity
    /** Author-authored order among findings that share a severity. Defaults to `0`. */
    sortIndex?: number
}

/** Props for {@link SubmissionFindingsList}. */
export interface SubmissionFindingsListProps {
    /** The findings, in ANY order ΓÇö the block re-sorts them itself (severity, then `sortIndex`). */
    findings: Array<SubmissionFinding>
    /**
     * Repo URL the attempt was submitted from ΓÇö turns each `location` into a
     * `blob/HEAD` deep-link. Omit ΓåÆ `location` still shows, as plain text.
     */
    repositoryUrl?: string
    /** Section label rendered above the card (e.g. `"Feedback"`). */
    label: string
    /** `true` ΓåÆ this list's own fetch is in flight; the card falls to its self-mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) ΓåÆ the card falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state title. Defaults to a standard "no findings yet" line. */
    emptyLabel?: string
    /** Truthy ΓåÆ the card falls to its error message (beats loading/empty ΓÇö see file header). */
    error?: unknown
    /** Retry handler ΓÇö paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button ΓÇö required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` ΓåÆ a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No feedback yet"
const ERROR_TITLE = "Could not load feedback"

/**
 * High ΓåÆ low, then by each finding's own authored order. The block's own
 * vocabulary, so a caller never has to pre-sort what it hands in.
 */
const sortFindings = (findings: ReadonlyArray<SubmissionFinding>): Array<SubmissionFinding> =>
    [...findings].sort((a, b) => {
        const rankDiff = SEVERITY_VISUAL[a.severity].rank - SEVERITY_VISUAL[b.severity].rank
        return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
    })

/**
 * `repositoryUrl` + a repo-relative `location` ΓåÆ a `blob/HEAD` deep-link. Ported
 * from `FindingAccordionItem` unchanged.
 */
const buildLocationHref = (location: string, repositoryUrl?: string): string | undefined =>
    repositoryUrl ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${location.replace(/^\//, "")}` : undefined

/**
 * Trigger icon: the severity glyph, its OWN tone colour independent of the
 * title text ΓÇö rides `titleStart`, not composed into `title` itself (┬º same
 * rule as `ChallengeDeliverableList`'s status icon).
 */
const findingIcon = (finding: SubmissionFinding): ReactNode => {
    const { icon: Icon, toneClassName } = SEVERITY_VISUAL[finding.severity]
    return (
        <Icon
            aria-hidden
            focusable="false"
            weight="bold"

            className={cn("size-3.5 shrink-0", toneClassName)}
        />
    )
}

/** Trailing trigger slot: the finding's file location, as a quiet chip. */
const findingLocationChip = (finding: SubmissionFinding): ReactNode | undefined =>
    finding.location ? (
        <Chip
            tone="default"
            text={finding.location}
            classNames={["shrink-0"]}

        />
    ) : undefined

/**
 * Panel content: the markdown detail, the linked file location, and the markdown
 * suggested fix ΓÇö each optional, each its own row (`related`: independent facts
 * about one finding, not a single unit of meaning).
 */
const findingPanel = (finding: SubmissionFinding, repositoryUrl: string | undefined): ReactNode => {
    const locationHref = finding.location ? buildLocationHref(finding.location, repositoryUrl) : undefined
    const locationRow = finding.location ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <MapPinIcon aria-hidden focusable="false" weight="bold" className="size-3 shrink-0 text-muted" />,
                () =>
                    locationHref ? (
                        <Typography
                            size="xs"
                            color="muted"
                            isLink
                            underlineOnHover
                            href={locationHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            text={finding.location}

                        />
                    ) : (
                        <Typography size="xs" color="muted" text={finding.location} />
                    ),
            ]}
        />
    ) : null
    const suggestionRow = finding.suggestion ? (
        <StackH
            gap={2}
            align="start"
            principle="icon-text"
            explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <LightbulbIcon aria-hidden focusable="false" weight="bold" className="size-3.5 shrink-0 text-muted" />,
                () => (
                    <div className="min-w-0 flex-1 text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.suggestion ?? ""}
                            measure="compact"

                        />
                    </div>
                ),
            ]}
        />
    ) : null
    return (
        <StackV
            gap={3}

            items={[
                ...(finding.detail ? [() => (
                    <div className="text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.detail ?? ""}
                            measure="compact"

                        />
                    </div>
                )] : []),
                () => locationRow,
                () => suggestionRow,
            ]}
        />
    )
}

const ErrorEmptyState = ({ onRetry, retryLabel }: ErrorEmptyStateProps) => (
    <AsyncContentError
        title={ERROR_TITLE}
        onRetry={onRetry}
        retryLabel={retryLabel}
    />
)

const PlainEmptyState = ({ title }: PlainEmptyStateProps) => (
    <AsyncContentEmpty title={title} />
)

/**
 * The "Feedback" findings card. See the file header for what this block owns
 * (severity vocabulary, sort order, the repo-URLΓåÆfile-link builder) and why
 * loading/empty/error all stay bounded inside the one `SurfaceCard.Accordion`
 * frame instead of swapping it out for `AsyncContent`'s own switch.
 *
 * @param props - {@link SubmissionFindingsListProps}
 */
const SubmissionFindingsList = ({
    findings,
    repositoryUrl,
    label,
    isLoading = false,
    isEmpty,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionFindingsListProps) => {
    // Error outranks even a stale loading/skeleton flag ΓÇö same priority order
    // `AsyncContent` itself documents ("error ΓåÆ loading ΓåÆ empty ΓåÆ content") ΓÇö so a
    // caller handing both `error` and `isLoading` still sees the error, not a
    // skeleton pretending the fetch is still running.
    const skeleton = !error && (isLoading || isSkeleton)
    const resolvedEmpty = !error && (isEmpty ?? findings.length === 0)

    const items: Array<SurfaceCardAccordionItem> = error
        ? []
        : sortFindings(findings).map((finding) => ({
            id: finding.id,
            titleStart: () => findingIcon(finding),
            title: finding.message,
            titleEnd: () => findingLocationChip(finding),
            body: () => findingPanel(finding, repositoryUrl),
        }))

    const emptyState = error
        ? () => <ErrorEmptyState onRetry={onRetry} retryLabel={retryLabel} />
        : resolvedEmpty
            ? () => <PlainEmptyState title={emptyLabel ?? EMPTY_LABEL_DEFAULT} />
            : undefined

    return (
        <div>
            <SurfaceCardAccordion
                label={label}
                items={items}
                isSkeleton={skeleton}
                emptyState={emptyState}


            />
        </div>
    )
}

export { SubmissionFindingsList }

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { SkeletonParagraph } from "@/components/blocks/skeleton/SkeletonParagraph"
import { SkeletonText } from "@/components/blocks/skeleton/SkeletonText"

/** Layout variant mirrored from {@link ContentBody} (V2 vs legacy). */
export type ContentBodySkeletonVariant = "v2" | "legacy"

/** Props for {@link ContentBodySkeleton}. */
export type ContentBodySkeletonProps = WithClassNames<undefined> & {
    /** `v2` ΓÇö article only; `legacy` ΓÇö toolbar + article. */
    variant?: ContentBodySkeletonVariant
}

/** One skeleton section: a heading width plus how many body lines follow it. */
interface MarkdownArticleSection {
    /** Tailwind width class for the section heading bar (e.g. `w-2/5`). */
    headingWidth: string
    /** Number of skeleton paragraph lines under the heading. */
    lines: number
}

/**
 * Section blocks (heading + body paragraph) standing in for the long-form lesson
 * body. Extra blocks also absorb the vertical space of the removed language-tab
 * row, which not every content renders.
 */
const MARKDOWN_ARTICLE_SECTIONS: Array<MarkdownArticleSection> = [
    { headingWidth: "w-2/5", lines: 4 },
    { headingWidth: "w-1/3", lines: 5 },
    { headingWidth: "w-1/4", lines: 4 },
    { headingWidth: "w-2/5", lines: 6 },
    { headingWidth: "w-1/3", lines: 3 },
]

/**
 * Markdown article block: section headings (`text-xl` in prose) + body paragraphs.
 * gap-3 between sections; gap-2 between the heading and paragraph within each section.
 */
const MarkdownArticleSkeleton = () => (
    <div className="flex flex-col gap-3">
        {MARKDOWN_ARTICLE_SECTIONS.map((section, index) => (
            // gap-2 = heading <-> paragraph (a tight sub-cluster within one section)
            <div key={index} className="flex flex-col gap-2">
                <SkeletonText size="xl" width={section.headingWidth} />
                <SkeletonParagraph size="sm" lines={section.lines} />
            </div>
        ))}
    </div>
)

/**
 * Icon action row mirroring {@link ActionToolbar} (bookmark, share, fullscreen).
 */
const ActionToolbarSkeleton = () => (
    <div className="flex items-center gap-2">
        {Array.from({ length: 3 }).map((_unused, index) => (
            <Skeleton
                key={index}
                className="size-9 rounded-xl"
            />
        ))}
    </div>
)

/**
 * Loading placeholder for {@link ContentBody} / {@link ContentBodyV2} / {@link ContentBodyLegacy}.
 * @param props - {@link ContentBodySkeletonProps}
 */
export const ContentBodySkeleton = ({
    className,
    variant = "v2",
}: ContentBodySkeletonProps) => {
    if (variant === "legacy") {
        // gap-3 = toolbar <-> article (within one skeleton block)
        return (
            <div className={cn("flex flex-col gap-3 text-sm text-muted", className)}>
                <ActionToolbarSkeleton />
                <MarkdownArticleSkeleton />
            </div>
        )
    }

    return (
        <div className={cn("flex flex-col overflow-x-auto text-sm text-muted", className)}>
            <MarkdownArticleSkeleton />
        </div>
    )
}

